// enrichment.js — adds notes, quizzes, exercises & projects to every course
// Exercises use a "safe grammar" verified against /api/run's JS-translation grader:
//   arithmetic (+,-,*,/,%,**), sum(), len(list), abs(), string concat, list indexing

function mkNote(chId,idx,title,intro,sections,tip){return{id:`${chId}-n${idx}`,type:'note',title,duration:"8 min",xp:50,intro,sections,tip}}
function mkQuiz(chId,idx,question,options,answer){return{id:`${chId}-q${idx}`,type:'quiz',title:"Knowledge Check",duration:"3 min",xp:50,question,options,answer}}
function mkEx(chId,idx,title,instructions,starterCode,expected,hint){return{id:`${chId}-e${idx}`,type:'exercise',title,duration:"10 min",xp:80,instructions,language:'python',starterCode,solution:starterCode,hint:hint||"print() the result",tests:[{expected}]}}
function mkProj(cid,idx,title,brief,objectives,deliverables,starterCode){return{id:`proj-${cid}-${idx}`,type:'project',title,brief,objectives,deliverables,language:'python',starterCode,duration:"2 hours",xp:200}}

// ==================== PER-COURSE ENRICHMENT ====================
// Each course id maps to: { notes: {chId: {title,intro,sections,tip}}, exercises: [{chId,title,instructions,code,expected}], quizzes: [{chId,question,options,answer}], projects: [{title,brief,objectives,deliverables,starterCode}] }

