// ─── Merge category enrichment modules written by sub-agents ───
import { mlEnrichment } from "./_enrich-ml.js";
import { dlEnrichment } from "./_enrich-dl.js";
import { genaiEnrichment } from "./_enrich-genai.js";
import { nlpEnrichment } from "./_enrich-nlp.js";
import { cvEnrichment } from "./_enrich-cv.js";
import { mlopsEnrichment } from "./_enrich-mlops.js";
import { ethicsEnrichment } from "./_enrich-ethics.js";
import { javaEnrichment } from "./_enrich-java.js";
import { exerciseFixes } from "./_fix-exercises.js";

const CAT = Object.assign({}, D,
  mlEnrichment || {}, dlEnrichment || {}, genaiEnrichment || {},
  nlpEnrichment || {}, cvEnrichment || {}, mlopsEnrichment || {}, ethicsEnrichment || {}, javaEnrichment || {});

function buildLessons(chId, idxBase, spec, kind){
  const out = [];
  if (kind === "note"){
    out.push(mkNote(chId, idxBase, spec.title, spec.intro, spec.sections, spec.tip));
  } else if (kind === "quiz"){
    out.push(mkQuiz(chId, idxBase, spec.question, spec.options, spec.answer));
  } else if (kind === "exercise"){
    out.push(mkEx(chId, idxBase, spec.title, spec.instructions, spec.code, spec.expected, spec.hint));
  }
  return out;
}

export function applyEnrichment(courses){
  for (const c of courses){
    const e = CAT[c.id];
    if (!e) continue;
    for (const ch of (c.chapters || [])){
      const add = [];
      let n = 0, q = 0, x = 0;
      const cspec = e.notes && e.notes[ch.id];
      if (cspec) add.push(...buildLessons(ch.id, n++, cspec, "note"));
      for (const qs of (e.quizzes || [])){ if (qs.chId === ch.id) add.push(mkQuiz(ch.id, 100+q++, qs.question, qs.options, qs.answer)); }
      for (const es of (e.exercises || [])){
        if (es.chId !== ch.id) continue;
        const lesson = mkEx(ch.id, 200+x++, es.title, es.instructions, es.code, es.expected, es.hint);
        const fix = exerciseFixes[c.id + "/" + lesson.id];
        if (fix){ lesson.starterCode = fix.code; lesson.solution = fix.code; lesson.tests[0].expected = fix.expected; }
        add.push(lesson);
      }
      if (add.length) ch.lessons.push(...add);
    }
    for (const [pi, p] of (e.projects || []).entries()){
      if (!(c.chapters || []).some(ch => ch.id === "projects" && true)){
        (c.chapters || []).push({
          id: "projects",
          title: "Practice Projects",
          duration: "2 hours",
          lessons: [mkProj(c.id, pi, p.title, p.brief, p.objectives, p.deliverables, p.starterCode)]
        });
      }
    }
  }
  return courses;
}
